<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionBank;
use App\Domain\QuestionBank\Repository\QuestionTaxonomyAssignmentRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionTaxonomySubjectRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionTaxonomyAssignmentRepository implements QuestionTaxonomyAssignmentRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function replaceForQuestion(string $questionId,array $taxonomySubjectIds):void{$this->entityManager->createQueryBuilder()->delete(QuestionTaxonomySubjectRecord::class,'a')->where('a.questionId=:questionId')->setParameter('questionId',$questionId)->getQuery()->execute();$now=new \DateTimeImmutable('now',new \DateTimeZone('UTC'));foreach(array_values(array_unique($taxonomySubjectIds)) as $subjectId){$record=new QuestionTaxonomySubjectRecord();$record->questionId=$questionId;$record->taxonomySubjectId=$subjectId;$record->createdAt=$now;$this->entityManager->persist($record);}} public function listSubjectIdsForQuestion(string $questionId):array{return array_map(static fn(QuestionTaxonomySubjectRecord $r)=>$r->taxonomySubjectId,$this->entityManager->createQueryBuilder()->select('a')->from(QuestionTaxonomySubjectRecord::class,'a')->where('a.questionId=:questionId')->setParameter('questionId',$questionId)->getQuery()->getResult());} }
